import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"reference/changelog.md","filePath":"reference/changelog.md","lastUpdated":1787052907000}`),a={name:`reference/changelog.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to “Changelog”">​</a></h1><h2 id="_0-2-3-2026-08-18" tabindex="-1">[0.2.3] - 2026-08-18 <a class="header-anchor" href="#_0-2-3-2026-08-18" aria-label="Permalink to “[0.2.3] - 2026-08-18”">​</a></h2><h3 id="fixed" tabindex="-1">Fixed <a class="header-anchor" href="#fixed" aria-label="Permalink to “Fixed”">​</a></h3><ul><li>A malformed <code>OPENGIST_URL</code> is no longer echoed into the log. That branch fires precisely when the variable does not hold a URL, which most often means the token was pasted into the wrong variable — and it then landed verbatim in the MCP host&#39;s log.</li></ul><h2 id="_0-2-2-2026-08-18" tabindex="-1"><a href="https://github.com/ni-c/opengist-mcp/compare/v0.2.1...v0.2.2" target="_blank" rel="noreferrer">0.2.2</a> - 2026-08-18 <a class="header-anchor" href="#_0-2-2-2026-08-18" aria-label="Permalink to “0.2.2 - 2026-08-18”">​</a></h2><h3 id="fixed-1" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-1" aria-label="Permalink to “Fixed”">​</a></h3><ul><li>The architecture diagram no longer depends on the reader&#39;s operating system. It carried a <code>prefers-color-scheme</code> block, which resolves against the OS rather than the theme toggle of GitHub or npm — so dark-mode readers on a light OS got the light artwork on a dark page. The README now uses <code>&lt;picture&gt;</code>, which is resolved against the page, and the <code>&lt;img&gt;</code> that npm falls back to brings its own card instead of a media query.</li></ul><h3 id="changed" tabindex="-1">Changed <a class="header-anchor" href="#changed" aria-label="Permalink to “Changed”">​</a></h3><ul><li>The diagram is generated from a single source, <code>docs/assets/architecture.source.svg</code>, by <code>npm run assets</code>. The four rendered copies had already drifted apart; CI now fails if one of them is edited by hand.</li><li><code>docs/public/og.png</code> is generated at exactly 1280x640, GitHub&#39;s recommended size for a social preview, instead of being drawn by hand.</li><li>The TypeScript major is now parked in <code>.github/dependabot.yml</code> with its reason, instead of living only as an <code>@dependabot ignore</code> on the closed PR #1 — that state is invisible to anyone reading the config and is lost if the PR is reopened.</li></ul><h2 id="_0-2-1-2026-08-16" tabindex="-1"><a href="https://github.com/ni-c/opengist-mcp/compare/v0.2.0...v0.2.1" target="_blank" rel="noreferrer">0.2.1</a> - 2026-08-16 <a class="header-anchor" href="#_0-2-1-2026-08-16" aria-label="Permalink to “0.2.1 - 2026-08-16”">​</a></h2><h3 id="fixed-2" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-2" aria-label="Permalink to “Fixed”">​</a></h3><ul><li>The documented value for the <code>scope</code> parameter of <code>list_gists</code> and <code>search_gists</code> was wrong: it is <code>mine</code>, not <code>own</code>. The docs, the getting-started smoke test and the demo tape were written from the tool descriptions instead of the schema, and a live call against a real instance rejected the value they showed.</li></ul><h3 id="changed-1" tabindex="-1">Changed <a class="header-anchor" href="#changed-1" aria-label="Permalink to “Changed”">​</a></h3><ul><li><code>homepage</code> points at <a href="https://opengist-mcp.ni-c.de" target="_blank" rel="noreferrer">opengist-mcp.ni-c.de</a> rather than the README anchor, so the npm page links to the documentation.</li><li>Published from CI through npm Trusted Publishing, so this release carries build provenance. 0.2.0 was published by hand and does not.</li></ul><h2 id="_0-2-0-2026-08-16" tabindex="-1"><a href="https://github.com/ni-c/opengist-mcp/compare/v0.1.0...v0.2.0" target="_blank" rel="noreferrer">0.2.0</a> - 2026-08-16 <a class="header-anchor" href="#_0-2-0-2026-08-16" aria-label="Permalink to “0.2.0 - 2026-08-16”">​</a></h2><h3 id="added" tabindex="-1">Added <a class="header-anchor" href="#added" aria-label="Permalink to “Added”">​</a></h3><ul><li>A <code>Dockerfile</code> and <code>.dockerignore</code>. The image is digest-pinned, runs as the unprivileged <code>node</code> user under <code>tini</code> and carries the MCP Registry ownership label. Multi-arch images (amd64, arm64) with an SBOM and build provenance are published to <code>ghcr.io/ni-c/opengist-mcp</code>.</li><li>A documentation site at <a href="https://opengist-mcp.ni-c.de" target="_blank" rel="noreferrer">opengist-mcp.ni-c.de</a> with a guide, the full tool reference and the security notes.</li><li>CI now runs CodeQL and a Trivy scan of the container image on both architectures in addition to the test matrix and <code>npm audit</code>. The runtime image ships without npm and corepack, whose vendored dependency trees were the only source of HIGH/CRITICAL findings on it.</li></ul><h3 id="changed-2" tabindex="-1">Changed <a class="header-anchor" href="#changed-2" aria-label="Permalink to “Changed”">​</a></h3><ul><li>The server now starts <strong>without</strong> <code>OPENGIST_URL</code>/<code>OPENGIST_TOKEN</code>: it completes the MCP handshake and lists its tools, and only a tool call fails with the setup instructions. Registries and sandbox inspectors start the server without secrets and could not enumerate the tools before. An invalid URL still exits, since that one could send the token to the wrong host.</li><li><code>get_user</code> returns an allowlisted set of fields instead of the raw API object, so fields Opengist may add later cannot appear in the model context on their own. A response that is not a user object is reported as an error naming the likely cause instead of being passed through.</li></ul><h3 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to “Security”">​</a></h3><ul><li><strong>Publishing content now needs a confirmation token.</strong> <code>create_gist</code> with <code>visibility: &quot;public&quot;</code> or <code>&quot;unlisted&quot;</code> refuses the first call and returns a single-use token, the same gate that widening an existing gist&#39;s visibility already had. Creating a public gist is the stronger of the two primitives — the content comes straight out of the model&#39;s context rather than from something already stored — and a required <code>visibility</code> field only prevents an <em>accidental</em> public default, not a directed one. <code>update_gist</code> gets the same gate when it writes files into a gist that is already public or unlisted; a call that makes the gist private in the same breath is not a disclosure and stays ungated.</li><li><code>update_gist</code> validates its file operations <strong>before</strong> asking for a confirmation, so a call that could never succeed no longer costs a confirmation round-trip and no token is ever issued for one.</li><li>The access token is now removed from <code>process.env</code> before any early return, not after the URL has been parsed. The credential-less start path is exactly the one where a token is set and something else is wrong — a typo in the URL, a half-filled config — and it used to leave the token readable in <code>/proc/&lt;pid&gt;/environ</code>.</li><li>Truncation and binary-content notes refer to a file by its index in the returned <code>files</code> array instead of quoting its name. A filename is written by whoever created the gist; interpolated into server-voice prose it could close the quoting and forge what reads as operator guidance. The name is still available to the model as the <code>filename</code> field of the entry, where it is data rather than prose.</li><li>The untrusted-metadata marker now also fires for the titles, descriptions and topics of embedded forks and of the gist a gist was forked from — those are written by <em>other</em> users, so a gist with no metadata of its own could carry theirs through unmarked. Commit author names get their own marker, and <code>change_status</code> is reduced to its four documented keys instead of being passed through.</li><li>Responses are refused past 8 MB, by <code>content-length</code> where one is declared and while reading otherwise. Every per-tool budget trims data that is already resident as a string, so without this ceiling a hostile instance could exhaust memory before any of them was consulted.</li><li>Confirmation tokens are compared in constant time, and the effect fingerprints they are bound to use the full SHA-256 digest instead of its first 64 bits.</li><li>The insecure-TLS dispatcher is now selected only for requests whose origin matches the configured instance, independent of the <code>redirect: &#39;error&#39;</code> that already prevented cross-origin hops.</li><li>The confirmation token of <code>update_gist</code> is now bound to the <strong>entire</strong> effect of the call, not just the new visibility. A confirmation obtained for &quot;make this public&quot; could previously be replayed with additional <code>fileOps</code>, <code>title</code> or <code>description</code> attached, so the user approved disclosure and silently got content changes as well. The refusal now also names the other changes the same call would make.</li><li><code>delete_gist_files</code> no longer echoes the filenames it is about to delete into the confirmation message, and the &quot;unknown filename&quot; error no longer echoes the requested or the existing filenames. Both are attacker-influenceable text in a message that a model reads — the rule the other confirmations already followed.</li><li>The &quot;nothing we send may be read as a deletion&quot; invariant is now backed by a measurement instead of an assumption. Verified against Opengist on 2026-08-15: on <strong>update</strong>, an entry with <code>content: &quot;&quot;</code> keeps the file and empties it; only an entry that is <code>null</code> or carries neither <code>content</code> nor <code>filename</code> deletes. On <strong>create</strong>, by contrast, a file with empty content is silently dropped — which is why <code>create_gist</code> requires non-empty content and <code>update_gist</code> does not.</li><li>Gist titles, descriptions and topics are now tagged as untrusted input in <code>list_gists</code>, <code>list_gist_forks</code>, <code>search_gists</code> and the gist detail. Only file contents carried that note before, while <code>list_gists</code> with <code>scope: &quot;public&quot;</code> returns the metadata of every gist on the instance — usually the first call of a session.</li><li>The release workflow installs <code>mcp-publisher</code> from a pinned version verified against a SHA-256 checksum instead of <code>releases/latest</code>, and runs <code>npm ci --ignore-scripts</code> in the job that holds the npm Trusted Publishing credential.</li></ul><h2 id="_0-1-0-2026-08-11" tabindex="-1"><a href="https://github.com/ni-c/opengist-mcp/releases/tag/v0.1.0" target="_blank" rel="noreferrer">0.1.0</a> - 2026-08-11 <a class="header-anchor" href="#_0-1-0-2026-08-11" aria-label="Permalink to “0.1.0 - 2026-08-11”">​</a></h2><h3 id="added-1" tabindex="-1">Added <a class="header-anchor" href="#added-1" aria-label="Permalink to “Added”">​</a></h3><ul><li>Initial release: MCP server for the Opengist REST API.</li><li>Read tools: <code>list_gists</code> (own, public, liked, forked, and per user), <code>search_gists</code>, <code>get_gist</code>, <code>get_gist_file</code>, <code>list_gist_commits</code>, <code>list_gist_forks</code>, <code>get_user</code>, <code>check_gist_like</code>.</li><li>Write tools: <code>create_gist</code>, <code>update_gist</code>, <code>delete_gist_files</code>, <code>delete_gist</code>, <code>fork_gist</code>, <code>set_gist_like</code>.</li><li><code>OPENGIST_READ_ONLY=true</code> registers only the read tools.</li><li><code>OPENGIST_INSECURE_TLS=true</code> accepts self-signed certificates, scoped to the Opengist connection instead of process-wide.</li></ul><h3 id="security-1" tabindex="-1">Security <a class="header-anchor" href="#security-1" aria-label="Permalink to “Security”">​</a></h3><ul><li>Irreversible operations (<code>delete_gist</code>, <code>delete_gist_files</code>, widening a gist&#39;s visibility) require a server-generated, single-use confirmation token that expires after five minutes. The token for <code>delete_gist_files</code> is bound to the exact set of filenames, so a confirmation cannot be replayed for a larger set.</li><li>Confirmation messages never echo gist titles, descriptions, topics or filenames, which are user-supplied text and could be used to manufacture a confirmation.</li><li>The raw Opengist <code>files</code> map is never exposed as a tool input, because an entry that is <code>null</code> or carries neither <code>content</code> nor <code>filename</code> deletes the file. <code>update_gist</code> takes explicit <code>write</code>/<code>rename</code> operations and asserts that nothing it sends can be read as a deletion; <code>delete_gist_files</code> is the only tool that deletes files.</li><li>A write to a filename that does not exist is refused unless <code>allowCreate</code> is set, and the refusal names a case-insensitive near match.</li><li>Responses that carry file content are tagged as untrusted input.</li><li>Requests refuse redirects, carry a 30 s timeout, and URL-encode path parameters that are additionally validated against <code>.</code>/<code>..</code> and control characters.</li><li>Upstream error bodies are truncated at 2000 characters and HTML error pages are dropped instead of being pushed into the model context.</li><li>The access token is removed from <code>process.env</code> after startup, and a URL containing credentials is rejected.</li></ul>`,26)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};